INSERT INTO eas.request_revision (id, request_id, revision_no, release_id, department_id, payload, amount_vnd, submitted_by, submitted_at, payload_sha256) VALUES ('b0000000-0000-4000-b000-000000000001', 'e0000000-0000-4000-e000-000000000001', 1, '00000003-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000002', '{"title": "Xin nghỉ phép năm du lịch gia đình tại Nha Trang", "reason": "Kế hoạch nghỉ mát thường niên cùng bố mẹ và gia đình, đã bàn giao toàn bộ task sprint cho bạn Nam hỗ trợ.", "end_date": "2026-09-11", "start_date": "2026-09-10", "handover_user_id": "00000002-0000-4000-8000-000000000009"}'::jsonb, NULL, '00000002-0000-4000-8000-000000000008', '2026-09-05 02:00:00+00:00', 'e674c9ecec99ac7601193d956aaffa43555227405508c9e61e5411ac15e90e59');
INSERT INTO eas.request_revision (id, request_id, revision_no, release_id, department_id, payload, amount_vnd, submitted_by, submitted_at, payload_sha256) VALUES ('b0000000-0000-4000-b000-000000000002', 'e0000000-0000-4000-e000-000000000002', 1, '00000003-0000-4000-8000-000000000001', '00000001-0000-4000-8000-000000000007', '{"title": "Xin nghỉ phép kết hôn và trăng mật", "reason": "Tổ chức đám cưới tại quê nhà Nghệ An và nghỉ tuần trăng mật theo chế độ công ty, đã hoàn tất tài liệu quy trình vận hành kho.", "end_date": "2026-10-19", "start_date": "2026-10-15", "handover_user_id": "00000002-0000-4000-8000-000000000037"}'::jsonb, NULL, '00000002-0000-4000-8000-000000000036', '2026-10-05 01:30:00+00:00', 'f76df889bb1a575ba9d2c8917f5b4bf03f408f86e7c967f114274fbf133dd612');
